package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math3.exception.MaxIterationsExceededException;
import org.apache.commons.math3.functional.UnivariateRealFunction;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class BrentOptimizer_BrentOptimizer_TriageGen0Test {

    @Test
    public void testConstructorAndDefaultSettings() {
        // Since the fields are private/protected and we can't access them directly 
        // without reflection, we verify the constructor executes without error.
        // The constructor sets specific internal state which is validated 
        // through the behavior of the optimize method.
        BrentOptimizer optimizer = new BrentOptimizer();
        UnivariateRealFunction function = x -> x * x;

        // Testing if the default settings allow a successful optimization
        try {
            double result = optimizer.optimize(function, GoalType.MINIMIZE, -10, 10);
            assertEquals(0.0, result, 1e-7);
        } catch (Exception e) {
            throw new AssertionError("Constructor failed to initialize optimizer correctly", e);
        }
    }

    @Test
    public void testOptimizeWithStartValue() throws Exception {
        BrentOptimizer optimizer = new BrentOptimizer();
        // Function: f(x) = (x-2)^2, minimum at x=2
        UnivariateRealFunction function = x -> Math.pow(x - 2.0, 2);

        double result = optimizer.optimize(function, GoalType.MINIMIZE, 0.0, 5.0, 4.0);

        // Check if result is close to 2.0
        assertEquals(2.0, result, 1e-6);
    }

    @Test
    public void testOptimizeMinimize() throws Exception {
        BrentOptimizer optimizer = new BrentOptimizer();
        // Function: f(x) = x^2, minimum at x=0
        UnivariateRealFunction function = x -> x * x;

        double result = optimizer.optimize(function, GoalType.MINIMIZE, -5.0, 5.0);

        assertEquals(0.0, result, 1e-6);
    }

    @Test
    public void testOptimizeMaximize() throws Exception {
        BrentOptimizer optimizer = new BrentOptimizer();
        // Function: f(x) = -(x-3)^2, maximum at x=3
        UnivariateRealFunction function = x -> -Math.pow(x - 3.0, 2);

        double result = optimizer.optimize(function, GoalType.MAXIMIZE, 0.0, 10.0);

        assertEquals(3.0, result, 1e-6);
    }

    @Test(expected = MaxIterationsExceededException.class)
    public void testMaxIterationsExceeded() throws Exception {
        // To trigger MaxIterationsExceededException, we need a function that 
        // makes the optimizer struggle or we would need to set a very low iteration count.
        // Since the constructor sets it to 100, we use a function that oscillates 
        // extremely rapidly to exhaust iterations.
        BrentOptimizer optimizer = new BrentOptimizer();

        UnivariateRealFunction function = x -> Math.sin(1.0 / (x + 0.0000000001));

        // This might not always trigger depending on the Brent logic, 
        // but is the standard way to test the exception in this context.
        optimizer.optimize(function, GoalType.MINIMIZE, 0.0, 1.0);
    }

    @Test(expected = Exception.class)
    public void testFunctionEvaluationException() throws Exception {
        BrentOptimizer optimizer = new BrentOptimizer();
        // Function that throws an exception during evaluation
        UnivariateRealFunction function = x -> {
            throw new RuntimeException("Evaluation error");
        };

        optimizer.optimize(function, GoalType.MINIMIZE, -1.0, 1.0);
    }
}
